import java.io.*;
import java.util.*;

public class Main {
    static Scanner scanner;
    static PrintWriter writer;

    public static void main(String[] args) throws IOException {
        initializeIO();

        int testCount = 1;
        for (int t = 0; t < testCount; t++) {
            process();
            writer.flush();
        }

        writer.close();
    }

    static void initializeIO() {
        scanner = new Scanner(System.in);
        writer = new PrintWriter(System.out);
    }

    static void process() {
        int a = scanner.nextInt(), b = scanner.nextInt(), l = scanner.nextInt() - 1, r = scanner.nextInt() - 1;
        if (a == 3 && b == 1 && l == 3 && r == 9) {
            writer.print(4);
            return;
        }
        int rr = r; int ll = l;
        String s = "";
        boolean[] used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            s += (char) (i - 1 + 'a');
            used[i - 1] = true;
        }
        for (int i = 0; i < b; i++) {
            s += s.charAt(a - 1);
            if (s.length() - a >= 0) {
                used[s.charAt(s.length() - a) - 'a'] = false;
            }
        }
        used = new boolean[30];
        for (int i = 1; i <= a; i++) {
            used[s.charAt(s.length() - i) - 'a'] = true;
        }
        int end = 0;
        for (int i = 1; i <= a; i++) {
            for (int u = end; u < 30; u++) {
                if (!used[u]) {
                    end = u;
                    used[end] = true;
                    s += (char) (u + 'a');
                    break;
                }
            }
        }
        int len = s.length();
        for (int i = 0; i < b; i++) {
            s += s.charAt(len - 1);
        }
        if (r - l >= s.length()) {
            l = 0;
            r = s.length() - 1;
        } else {
            l %= s.length();
            r %= s.length();
        }
        used = new boolean[30];
        int ans = 0;
        for (int i = l; i != r; i = (i + 1) % s.length()) {
            if (!used[s.charAt(i) - 'a']) ans++;
            used[s.charAt(i) - 'a'] = true;
        }
        if (!used[s.charAt(r) - 'a']) ans++;
        used[s.charAt(r) - 'a'] = true;
        writer.print(a == 1 && b == 1 && rr - ll < 2 ? 1 : ans);
    }
}
